insert into public.communities (name, slug, description)
select p.name, p.slug, p.description
from proposed p
where not exists (
  select 1 from public.communities existing
  where lower(existing.name) = lower(p.name) or existing.slug = p.slug
)
on conflict do nothing;
commit;
